const H := 0.01  # finite-difference step size

func _gradient(x: float, y: float, surface: int) -> Vector2:
	var df_dx = (_compute_loss(x + H, y, surface) - _compute_loss(x - H, y, surface)) / (2.0 * H)
	var df_dy = (_compute_loss(x, y + H, surface) - _compute_loss(x, y - H, surface)) / (2.0 * H)
	return Vector2(df_dx, df_dy)

# Finite differences: numerical gradient
# Analytic gradient is faster and more precise
# but FD works for ANY function where you can evaluate points.
# This is why FD is the teaching choice here.

class Adam:
	var position: Vector2
	var m: Vector2 = Vector2.ZERO  # first moment (momentum)
	var v: Vector2 = Vector2.ZERO  # second moment (variance)
	var t: int = 0
	var learning_rate: float = 0.01
	var beta1: float = 0.9
	var beta2: float = 0.999
	var eps: float = 1e-8

	func step(grad: Vector2) -> void:
		t += 1
		m = m * beta1 + grad * (1.0 - beta1)
		v = v * beta2 + grad * grad * (1.0 - beta2)

		# Bias correction for early steps
		var m_hat = m / (1.0 - pow(beta1, t))
		var v_hat = v / (1.0 - pow(beta2, t))

		# Per-parameter adaptive step
		position -= learning_rate * m_hat / (v_hat.sqrt() + eps)
